mapper.select:
SELECT * FROM emoji
WHERE category = #{category}
ORDER BY hot_score DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT * FROM emoji
ORDER BY hot_score DESC, id DESC
LIMIT #{limit}

SELECT e.* FROM emoji e
INNER JOIN recent_use r ON r.emoji_id = e.id AND r.user_id = #{userId}
ORDER BY r.last_used_at DESC
LIMIT #{limit}

SELECT e.* FROM emoji e
INNER JOIN favorite f ON f.emoji_id = e.id AND f.user_id = #{userId}
ORDER BY f.create_time DESC
